from flask import Flask, request, Response
import os

app = Flask(__name__)

@app.route('/logs', methods=['GET'])
def get_logs():
    file_name = request.args.get('file')

    if not file_name:
        return Response(status=400, description="Missing 'file' parameter")

    # Prevent directory traversal by ensuring the path stays within ./logs/
    base_dir = './logs/'
    if not os.path.isdir(base_dir):
        return Response(status=403, description="Directory does not exist")

    # Construct a safe file path
    file_path = os.path.join(base_dir, file_name)

    # Double-check that the resolved path is still within the base directory
    real_base = os.path.realpath(base_dir)
    real_file = os.path.realpath(file_path)

    if not real_file.startswith(real_base):
        return Response(status=403, description="Access denied")

    if not os.path.isfile(file_path):
        return Response(status=404, description="File not found")

    try:
        with open(file_path, 'r') as f:
            lines = f.readlines()

        # Get the last 10 lines
        last_10_lines = lines[-10:] if len(lines) >= 10 else lines

        # Join lines and return as plain text
        log_content = ''.join(last_10_lines)
        return Response(log_content, mimetype='text/plain')

    except Exception as e:
        return Response(status=500, description=str(e))

if __name__ == '__main__':
    app.run(debug=True)
