from typing import Any, Dict, List, Union

# Helper to determine the type of a value for serialization
def get_type_name(value: Any) -> str:
    if isinstance(value, bool):
        return "bool"
    elif isinstance(value, int):
        return "int"
    elif isinstance(value, float):
        return "float"
    elif isinstance(value, str):
        return "str"
    elif isinstance(value, list):
        return "list"
    elif isinstance(value, dict):
        return "dict"
    else:
        return "unknown"

def serialize_message(msg: Dict[str, Any]) -> bytes:
    """
    Serializes a dictionary message into bytes.

    Format:
    - Length of the entire payload (4 bytes, big-endian)
    - Message type identifier (1 byte): 'd' for dict, 'l' for list, 'b' for bool, 'i' for int, 'f' for float, 's' for str
    - Type name length (2 bytes, big-endian)
    - Type name string
    - Value serialized according to type

    Includes a simple integrity check (CRC32) appended at the end.
    """
    def serialize_value(value: Any) -> bytes:
        if isinstance(value, bool):
            return struct.pack('b', 1 if value else 0)
        elif isinstance(value, int):
            return struct.pack('i', value)
        elif isinstance(value, float):
            return struct.pack('d', value)
        elif isinstance(value, str):
            return value.encode('utf-8')
        elif isinstance(value, list):
            # Serialize as comma-separated string of serialized values
            items = [serialize_value(item) for item in value]
            return ','.join(str(len(x)) + x.decode('utf-8') if isinstance(x, bytes) else str(len(x)) + x for x in items).encode('utf-8')
        elif isinstance(value, dict):
            # Serialize as key-value pairs separated by semicolons
            parts = []
            for k, v in value.items():
                key_bytes = serialize_value(k)
                val_bytes = serialize_value(v)
                parts.append(key_bytes + b';' + val_bytes)
            return b''.join(parts)
        else:
            raise ValueError(f"Unsupported type: {type(value)}")

    # Serialize the main message
    serialized_data = serialize_value(msg)

    # Calculate CRC32 for integrity check
    crc = struct.pack('>I', hashlib.crc32(serialized_data) & 0xffffffff)

    # Build the final packet
