/**
 * Copies the string 'src' into the buffer 'dst', converting every letter to upper case.
 * 
 * Parameters:
 *   dst     - Destination buffer (must be large enough to hold the result)
 *   dst_size - Size of the destination buffer in bytes
 *   src     - Source string to copy and convert
 * 
 * Note: This function assumes 'src' is a valid null-terminated string.
 * It performs bounds checking based on dst_size to prevent buffer overflows.
 */
void to_upper_copy(char *dst, size_t dst_size, const char *src) {
    if (dst == NULL || src == NULL || dst_size == 0) {
        return;
    }

    // Calculate the length of the source string
    size_t src_len = strlen(src);

    // Ensure there is room for the null terminator in the destination buffer
    if (src_len >= dst_size) {
        // If the source string is too long to fit, we can either truncate or return.
        // To ensure a valid C string result without truncation logic specified,
        // we will copy as much as fits and terminate at the available space.
        size_t max_copy = dst_size - 1; // Leave room for null terminator
        size_t actual_len = (src_len < max_copy) ? src_len : max_copy;

        for (size_t i = 0; i < actual_len; i++) {
            dst[i] = toupper((unsigned char)src[i]);
        }
        dst[actual_len] = '\0';
    } else {
        // Safe to copy the entire string
        for (size_t i = 0; i < src_len; i++) {
            dst[i] = toupper((unsigned char)src[i]);
        }
        dst[src_len] = '\0';
    }
}
