#include <ctype.h>

/**
 * Reads one line from standard input into the buffer `out`.
 * The buffer size is `out_len` bytes.
 * The trailing newline character (if present) is removed.
 * 
 * Security considerations:
 * - Uses fgets to prevent buffer overflow and handle newlines safely.
 * - Checks if the read string ends with a newline and removes it.
 * - Ensures null termination even if no newline is found within bounds.
 */
void read_username(char *out, size_t out_len) {
    // Validate input parameters to prevent use-after-free or invalid pointer access
    if (out == NULL || out_len == 0) {
        return;
    }

    // Read a line from stdin into the buffer.
    // fgets reads until a newline is encountered or EOF, and stores at most out_len - 1 characters.
    // It guarantees null termination of the string in the buffer.
    if (fgets(out, (size_t)out_len, stdin) == NULL) {
        // If reading fails (e.g., EOF immediately), we still have a valid null-terminated string
        // but it might be empty or contain only non-newline characters.
        return;
    }

    // Check if the last character is a newline and remove it.
    // We need to ensure there is at least one character before checking the last one.
    size_t len = strlen(out);

    // If the buffer contains more than 1 character and the last one is a newline, remove it.
    // Note: fgets ensures out_len-1 characters are stored plus null terminator.
    // So if len == out_len - 1, there was no newline in the input (or it was at the very end 
    // but fgets might have included it if it fits, actually fgets includes the newline if space permits).
    // Let's refine: If the string ends with '\n', we remove it.

    if (len > 0 && out[len - 1] == '\n') {
        out[len - 1] = '\0';
        len--; // Logical length after removal

        // Optional: Trim leading/trailing whitespace if desired, but the prompt only asks for trailing newline.
        // However, sometimes "removing trailing newline" implies we might want to strip spaces too? 
        // The prompt specifically says "removes the trailing newline", so we stick to that.
    }

    // Ensure null termination just in case (though fgets guarantees it)
    out[len] = '\0';
}
