def download_file():
    filename = request.args.get('filename')

    # Basic validation to ensure the file exists and is a string
    if not filename:
        return 'Missing filename parameter', 400

    # Define the allowed directory path
    directory = os.path.join(os.path.dirname(__file__), 'data', 'reports')

    # Ensure the directory exists
    if not os.path.exists(directory):
        return 'Directory does not exist', 500

    # Construct the full file path
    file_path = os.path.join(directory, filename)

    # Prevent directory traversal attacks by ensuring the resolved path is within the allowed directory
    try:
        real_file_path = os.path.realpath(file_path)
        real_directory = os.path.realpath(directory)

        if not real_file_path.startswith(real_directory + os.sep) and real_file_path != real_directory:
            return 'Access denied', 403

        # Check if the file exists
        if not os.path.exists(real_file_path):
            return 'File not found', 404

        # Ensure it's a file, not a directory
        if not os.path.isfile(real_file_path):
            return 'Invalid file path', 400

    except (ValueError, TypeError):
        return 'Invalid filename parameter', 400

    # Send the file with the original filename
    return send_from_directory(directory, filename)

