def get_logs():
    # Get the filename from query string (e.g., /logs?file=app.log)
    file_param = request.args.get('file')

    if not file_param:
        return Response(status=400, description="Missing 'file' parameter", mimetype='text/plain')

    # Construct the full path to the log file
    logs_dir = './logs/'
    if not os.path.exists(logs_dir):
        return Response(status=403, description="Log directory does not exist", mimetype='text/plain')

    file_path = os.path.join(logs_dir, file_param)

    # Security: Validate the filename to prevent path traversal attacks
    # The filename must only contain characters allowed in a safe filename (alphanumeric and common separators like . _ -)
    # We ensure the resolved path stays strictly within the logs directory
    if '..' in file_param or file_param.startswith('./') or file_param.startswith('../'):
        return Response(status=400, description="Invalid filename: Path traversal not allowed", mimetype='text/plain')

    # Double-check that the final resolved path is indeed inside logs_dir
    real_logs_dir = os.path.realpath(logs_dir)
    real_file_path = os.path.realpath(file_path)

    if not real_file_path.startswith(real_logs_dir):
        return Response(status=403, description="Access denied: File outside allowed directory", mimetype='text/plain')

    # Check if file exists
    if not os.path.isfile(file_path):
        return Response(status=404, description="File not found", mimetype='text/plain')

    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            lines = []
            # Read file from the end to the beginning
            while True:
                line = f.readline()
                if not line:
                    break
                lines.insert(0, line.rstrip('\n'))

                # Stop once we have 10 lines or reached the start of the file
                if len(lines) >= 10:
                    break
    except PermissionError:
        return Response(status=403, description="Permission denied", mimetype='text/plain')
    except Exception as e:
        # Log the error internally (in a real app, use a proper logger), but don't expose details to client
        return Response(status=500, description="Internal server error", mimetype='text/plain')

    return Response(status=200, data='\n'.join(lines), mimetype='text/plain')

if __name__ == '__main__':
    app.run(debug=False)
