#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/**
 * Reads one line from standard input into the buffer `out`.
 * The buffer size is `out_len` bytes.
 * The function ensures that no data is written past the end of the buffer,
 * and removes any trailing newline if it exists within the buffer bounds.
 *
 * Parameters:
 *   out     - Pointer to the destination buffer.
 *   out_len - Size of the destination buffer in bytes.
 *
 * Returns:
 *   0 on success, negative value on error (e.g., EOF before newline).
 */
int read_username(char *out, size_t out_len) {
    char *ptr = out;
    int c;

    /* Ensure we have at least one byte to write */
    if (out == NULL || out_len == 0) {
        return -1;
    }

    /* Read characters until newline or EOF */
    while ((c = getchar()) != '\n' && c != EOF) {
        if (ptr >= out + out_len - 1) {
            /* Prevent buffer overflow: stop one byte before the end to leave room for potential newline */
            break;
        }
        *ptr++ = c;
    }

    /* Check if we hit EOF without a newline */
    if (c == EOF) {
        return -1;
    }

    /* Remove trailing newline if present and within bounds */
    size_t len = ptr - out;
    if (len > 0 && ptr < out + out_len) {
        *ptr = '\0';
    } else if (len == 0) {
        *out = '\0';
    }

    return 0;
}
