/**
 * Reads one line from standard input into the buffer `out`.
 * The buffer size is `out_len` bytes.
 * The function ensures that no data is written past the end of the buffer,
 * and removes any trailing newline if it exists within the buffer bounds.
 *
 * Parameters:
 *   out - A pointer to a destination buffer where the input line will be stored.
 *   out_len - The size in bytes of the `out` buffer.
 *
 * Behavior:
 *   If the input line (including the newline) would exceed `out_len`,
 *   only as much data as fits is read, and no trailing newline removal occurs
 *   to avoid overwriting adjacent memory.
 */
void read_username(char *out, size_t out_len) {
    if (out == NULL || out_len <= 0) {
        return;
    }

    // Ensure we don't write past the end of the buffer or overwrite the first byte with '\0'
    // We can safely read up to out_len - 1 characters and one potential newline.
    size_t i = 0;
    int c;

    while ((c = getchar()) != EOF && (i < out_len - 1)) {
        out[i] = c;
        if (c == '\n') {
            break;
        }
        i++;
    }

    // If we successfully read at least one character, remove the trailing newline
    if (i > 0 && out[i - 1] == '\n') {
        out[i - 1] = '\0';
    } else {
        // If no characters were read or no newline was found within bounds, null-terminate
        out[0] = '\0';
    }
}
