    """Reads the last n lines from a file safely."""
    if not os.path.isfile(filepath):
        return None

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            # Read entire content and use rsplit to get last n lines efficiently
            content = f.read()
            lines = content.splitlines()

            if len(lines) <= n:
                return '\n'.join(lines)
            else:
                return '\n'.join(lines[-n:])
    except IOError:
        return None

