    # We resolve the absolute path and check if it starts with the base directory.
    logs_dir = './logs/'

    # Construct potential full path
    target_path = os.path.join(logs_dir, file_param)

    # Resolve to absolute path to handle relative paths or symlinks correctly
    abs_target = os.path.abspath(target_path)
    abs_logs_dir = os.path.abspath(logs_dir)

    # Check if the resolved path is within the logs directory
    if not (abs_target.startswith(abs_logs_dir + os.sep) or abs_target == abs_logs_dir):
        abort(403, description='Path traversal attempt detected.')

    # Additional check to ensure it's a file
    if not os.path.isfile(abs_target):
        abort(404, description='File not found.')

    lines = get_last_n_lines(abs_target)

    if lines is None:
