from urllib.parse import quote_plus

def encode_token(data):
    """
    Encodes a dictionary of plain data into a URL-safe text token (str).

    Supports: strings, numbers, booleans, lists, and nested dicts.

    Args:
        data (dict): The input data to encode.

    Returns:
        str: A URL-safe encoded string representation of the dictionary.
    """
    # Ensure input is a dict
    if not isinstance(data, dict):
        raise TypeError("Input data must be a dictionary.")

    # Convert non-serializable types (like sets or custom objects) by filtering them out
    def serialize_value(val):
        if isinstance(val, bool):
            return "true" if val else "false"
        elif isinstance(val, int) or isinstance(val, float):
            return str(val)
        elif isinstance(val, str):
            return val
        elif isinstance(val, list):
            return "[" + ", ".join(serialize_value(item) for item in val) + "]"
        elif isinstance(val, dict):
            items = [f"{k}={serialize_value(v)}" for k, v in val.items()]
            return "{" + ",".join(items) + "}"
        else:
            # Fallback for unexpected types; convert to string representation
            return str(val)

    serialized = serialize_value(data)

    # URL encode the result using quote_plus which handles spaces and special characters safely
    return quote_plus(serialized, safe='')

