    size_t len_first = strlen(first);
    size_t len_last = strlen(last);

    // Total required size: len1 + 1 (space) + len2 + 1 (null terminator)
    size_t total_len = len_first + 1 + len_last + 1;

    // Allocate exactly the required amount of memory
    char *fullname = (char *)malloc(total_len);
    if (fullname == NULL) {
        return NULL; // Memory allocation failed
    }

    // Copy first name
    memcpy(fullname, first, len_first);

    // Append space
    fullname[len_first] = ' ';

    // Copy last name
    memcpy(fullname + len_first + 1, last, len_last);

    // Set null terminator
    fullname[total_len - 1] = '\0';

    return fullname;
