    """Reads the last n lines from a file and returns them as a list of strings."""
    if not os.path.exists(filepath):
        return None

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            # Seek to the end of the file
            f.seek(0, 2)
            file_size = f.tell()

            # If file is empty or smaller than n lines (handling single line files correctly)
            if file_size == 0:
                return []

            # We'll read the whole file into a list of lines for simplicity given Flask's context,
            # but in a high-performance scenario, we'd seek backwards. 
            # Given the requirement is simple and log files are usually text-based lists,
            # reading all and slicing is robust against edge cases like CRLF vs LF mixing.
            content = f.read()
            lines = content.splitlines()

            if len(lines) > n:
                return lines[-n:]
            else:
                return lines
    except Exception as e:
        # In a real app, log this error separately; here we just return None to trigger 404/500 logic handled below
        return None

