# --- Helper Functions for Serialization/Deserialization ---

def _serialize_value(value: Any) -> bytes:
    """Helper to serialize a primitive value to bytes."""
    if isinstance(value, bool):
        # Handle boolean first before int check in Python
        return struct.pack('B', 0 if value is False else 1)
    elif isinstance(value, (int, float)):
        # Use a fixed size for simplicity (64-bit signed integer/float representation)
        # In production, you might need to distinguish between int and float based on range or type tags.
        return struct.pack('q', int(value))
    elif isinstance(value, str):
        # Encode string as UTF-8 then prepend length
        encoded = value.encode('utf-8')
        return struct.pack('I', len(encoded)) + encoded
    elif isinstance(value, list):
        return _serialize_list(value)
    elif isinstance(value, dict):
        return _serialize_dict(value)
    else:
        raise ValueError(f"Unsupported type for serialization: {type(value)}")

def _serialize_list(lst: list) -> bytes:
    """Helper to serialize a list of values."""
    if not lst:
        return struct.pack('I', 0) + struct.pack('i', 0)

    # Pack the length of items first
    item_count = len(lst)
    data = struct.pack('I', item_count)

    for item in lst:
        data += _serialize_value(item)

    return data

def _serialize_dict(dct: dict) -> bytes:
    """Helper to serialize a dictionary."""
    # To maintain order and integrity, sort keys or use a fixed order. 
    # Here we assume insertion order is preserved in Python 3.7+, but we serialize key-value pairs sequentially.
    if not dct:
        return struct.pack('I', 0) + struct.pack('i', 0)

    items = list(dct.items())
    item_count = len(items)
    data = struct.pack('I', item_count)

    for key, value in items:
        # Assuming keys are strings for this exercise; if mixed, add a type tag.
        if not isinstance(key, str):
            raise ValueError("Dictionary keys must be strings.")

        key_bytes = _serialize_value(key)
        val_bytes = _serialize_value(value)
        data += key_bytes + val_bytes

    return data

