@app.route('/download', methods=['GET'])
def download_file():
    filename = request.args.get('filename')

    # Security: Validate the filename to prevent path traversal attacks.
    # We only allow filenames that start with a safe character and contain no path separators.
    if not filename or '..' in filename or '/' in filename or '\\' in filename:
        return make_response(('Invalid filename', 400))

    # Construct the full file path safely by joining base directory and filename
    # We do not use os.path.join directly to allow user-supplied filenames that might start with a slash
    filepath = os.path.join(DATA_DIR, filename)

    # Double-check if the file exists
    if not os.path.isfile(filepath):
        return make_response(('File not found', 404))

    # Additional check: Ensure the resolved path is actually within DATA_DIR to prevent other traversal tricks
    real_filepath = os.path.realpath(filepath)
    real_data_dir = os.path.realpath(DATA_DIR)
    if not real_filepath.startswith(real_data_dir + os.sep) and real_filepath != real_data_dir:
        return make_response(('Access denied', 403))

    # Send the file with appropriate headers
    response = send_from_directory(DATA_DIR, filename)
    response.headers['Content-Disposition'] = f'attachment; filename="{filename}"'

    return response

@app.route('/')
def index():
    return 'Welcome to the Secure File Server. Use /download?filename=<name> to download files.'

